css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: calc(var(--loader-size) * .5); display: flex; align-items: flex-end; justify-content: space-between; }
.loader span { width: calc(var(--loader-size) * .1); height: 100%; background: var(--accent); border-radius: calc(var(--loader-size) * .02); transform-origin: 50% 100%; animation: domino calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span:nth-child(1) { animation-delay: 0s; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .12); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .48); }
@keyframes domino { 0% { transform: rotate(0deg); } 30%, 55% { transform: rotate(62deg); } 85%, 100% { transform: rotate(0deg); } }
